import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AR everyday-crime stories.
extension FollowUpCases {
    static let batchAR: [CaseTemplate] = [toolShoplift, mailboxAgain, expiredPermitAgain, raceDwlr, trailheadAgain, porchReturns, interfereAgain, tillAgain, cardAgain, grandmaSecondCheck, breathRefusalAgain, refereeThreat, postsAgain, employeeFilesSecond, pharmacyThreatsAgain, toddlerAgain, grabAgainParty, batAgain, fifthDwi, debtThreatGarage]

    static let toolShoplift = SmallCases.make(
        key: "story.followup.toolShoplift",
        category: .property,
        headlines: ["Shopper Stopped With Tools at Different Store", "Defendant From Drill Case Caught at Home Improvement Chain"],
        law: "larcenyMerchant",
        spec: "Took tools valued at $240 from {V}, a home improvement store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a loss prevention officer at a home improvement store watched {D} put two cordless tools in a backpack and leave through the garden exit. {DL} says the backpack came in with the tools. The loss was put at $240.",
        state: [E(.video, 3, "Garden Exit Camera", "{D} leaves with a loaded backpack."), E(.physical, 2, "Tools", "Two tagged tools in the backpack.", .search)],
        defense: [E(.statement, 1, "Own Tools", "{DL} says the tools were {D.his} own.")],
        role: "Loss prevention officer",
        exam: [.direct("What is your job?", "\"I'm a loss prevention officer. I watch the floor and cameras and stop people who leave without paying.\""), .direct("What did you see that day?", "\"I watched {DL} take two cordless tools from a shelf and put them into a backpack in the aisle.\""), .direct("What did you do?", "\"I followed {D.him} through the store and watched {D.him} walk out through the garden exit without stopping at a register.\""), .direct("What does the garden exit camera show?", "\"It shows {DL} leaving with the backpack loaded and heading toward the parking lot.\""), .direct("What did you find in the backpack?", "\"Two tagged cordless tools with store price stickers still attached, worth about two hundred forty dollars.\""), .direct("What did {DL} say?", "\"{D.He} said the tools were {D.his} own and that the backpack came in with them.\""), .cross("You didn't see {DL} pick up the tools from the shelf?", "\"I saw it on camera from a distance, but the shelf angle isn't perfect.\""), .cross("Many people bring their own tools in?", "\"Some do, but these had our price tags and our inventory codes.\""), .cross("{DL} stopped when you approached?", "\"Yes, {D.he} stopped and didn't try to run.\""), .cross("{DL} didn't threaten you?", "\"No, there was no threat and no struggle.\""), .cross("The tools were returned?", "\"Yes, both were returned to the shelf, undamaged.\"")],
        theory: ("{D} took tools.", "Own tools."),
        allocution: "\"I'm sorry for the trouble at that store. The backpack was mine, and the tools I own came in with it, and I understand how it looked at the garden exit. I've been in this courtroom before, and I know that makes my word harder to accept. I'll bring my receipts next time.\"",
        truths: ("The tools bore the store's price tags.", "A store employee handed {DL} the tools to hold at the register."),
        defendant: [.direct("Why did you have the tools?", "\"I thought they were mine. I bring tools in my backpack to jobs, and I got them mixed up.\""), .direct("Did you pick them up in the store?", "\"I looked at some tools but I never intended to take anything I hadn't paid for.\""), .direct("Why did you leave through the garden exit?", "\"It's closer to where I'd parked. I didn't think of it as avoiding the registers.\""), .direct("What happened when the officer stopped you?", "\"I stopped, showed the backpack, and told the officer what I thought. I gave everything back.\""), .direct("Did you see the price tags?", "\"I noticed them afterward. I should have looked before I walked out.\""), .direct("What would you tell the store?", "\"I'm sorry for the confusion. I'll pay for any loss and I won't take chances with bags again.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have been extra careful in a store.\""), .cross("You left without paying?", "\"Yes, though I thought they were mine. I should have checked.\""), .cross("The tools had the store's tags?", "\"They did, and that shows I should have looked closer.\""), .cross("You walked past the registers?", "\"I did, and I understand how that looks.\""), .cross("You'll leave your own tools at home when shopping?", "\"Yes, and I'll keep my backpack closed in the store from now on.\"")],
        openings: ("A loss prevention officer at a home improvement store watched {D} take two cordless tools from a shelf, put them in a backpack, and leave through the garden exit without paying. The loss was $240, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will say the tools in the backpack were {D}'s own, brought from home for a job, and that {D} never took anything from the shelf. {D} left by the garden exit because it was nearest the truck."),
        closings: ("The garden exit camera shows {D} leave with a loaded backpack, and the officer watched the tools go in from the shelf. After {PRIOR}, {DL} knew exactly what walking out unpaid means.", "A backpack of tools from home looks like a backpack of tools from a shelf on a camera. The State must prove the tools were the store's and that {D} meant to keep them."),
        timeline: [(0, "{DL} enters with an empty bag."), (0, "{DL} leaves by the garden exit.")],
        identified: "A garden exit camera.",
        impact: "Same chain, same problem. We lose thousands every year through that garden exit, and every incident means paperwork and a lost afternoon for my loss prevention staff. Two cordless tools walked out in a backpack. I'm tired of watching the same type of loss come back.",
        genders: ["D": .male])

    static let mailboxAgain = SmallCases.make(
        key: "story.followup.mailboxAgain",
        category: .property,
        headlines: ["Another Night of Smashed Mailboxes", "Pickup Seen Near Damaged Boxes, Registered to Defendant From Earlier Case"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a mailbox, causing damage of $240, on {DATE}.",
        ages: 18...26,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, four mailboxes were smashed on a different road. A porch camera showed a car slowing at each. The car belongs to {D}. {DL} says the car was parked at home. Damage was put at $240.",
        state: [E(.video, 3, "Porch Camera", "A car slows and a bat swings."), E(.document, 3, "Registration", "The car is registered to {D}.")],
        defense: [E(.statement, 1, "Parked", "{DL} says the car was parked at home.")],
        role: "Resident",
        exam: [.direct("What happened to your mailbox?", "\"I woke up and found my mailbox smashed and lying in the grass, along with three others on my road.\""), .direct("How do you know it was a car?", "\"My porch camera shows a car slowing at each box and someone leaning out the window with a bat.\""), .direct("What does the camera show?", "\"The car slows, a bat swings at the box, and the car speeds away down the road.\""), .direct("What was the damage?", "\"My box was broken off its post. The post was cracked, and a replacement was about two hundred forty dollars.\""), .direct("Who owns the car?", "\"The deputy told me the car on the video is registered to {DL}, who lives a few miles from here.\""), .direct("What did {DL} say?", "\"{D.He} said the car was parked at home that night, and someone else must have used it.\""), .cross("You can't see who was inside?", "\"No, the camera shows the car and an arm and a bat, but not a face.\""), .cross("The video is dark?", "\"Yes, it was night and the picture is dim. I can describe the car but not the driver.\""), .cross("You've never had trouble with {DL}?", "\"No. I don't know {D.him} personally, and I've had no dispute with {D.him}.\""), .cross("Four mailboxes were hit?", "\"Yes, all on the same stretch. Mine was the third.\""), .cross("You didn't see the car in person?", "\"No, only on the camera the next morning.\"")],
        theory: ("{D} smashed mailboxes again.", "A parked car."),
        allocution: "\"I'm sorry for the damage to those mailboxes. My car was parked at home that night, and I wasn't on that road. I've been in this courtroom before, and I know my car is easy to point at. I hope the court looks at where the car actually was.\"",
        truths: ("The bat in the car's trunk had fresh chips.", "The car had been reported stolen that evening."),
        defendant: [.direct("Where was your car that night?", "\"Parked at my house, where I always leave it. I was asleep inside, and my keys were on the hook.\""), .direct("Do you know who used your car?", "\"No. I didn't know it was used until the deputy told me. I wouldn't have lent it to anyone that night.\""), .direct("Did you smash those mailboxes?", "\"No. I would never do that. I didn't know the people on that road and had no reason to.\""), .direct("Who has access to your car?", "\"My roommate has a key, and my cousin has borrowed it before. I don't know who might have taken it.\""), .direct("What did you tell the deputy?", "\"I told the deputy where the car was and who had a key, so the deputy could check with them.\""), .direct("What would you tell the court?", "\"It wasn't me. I'd ask the court to look at who else had the car and not just whose name is on the registration.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know people think the worst of me. That doesn't make this mine.\""), .cross("The car is registered to you?", "\"It is, but registration isn't the same as who was driving that night.\""), .cross("You can't prove it was parked at home?", "\"Only by my word and my roommate's. We were both home that night.\""), .cross("Your cousin has borrowed it before?", "\"Yes, but not that night, as far as I know. I haven't been able to ask him.\""), .cross("You'll help find who did it?", "\"Yes. I'll give the deputies the names of everyone with a key and cooperate fully.\"")],
        openings: ("Four mailboxes on a different road were smashed with a bat, and a porch camera shows a car slowing at each box with someone leaning out the window. The car is registered to {D}, and {DL} came before this court in {PRIORDATE} over {PRIOR}. Damage was put at $240.", "The defense will say {D}'s car was parked at home that night and that anyone could have driven past those boxes. A car on a camera is not a person."),
        closings: ("The camera shows a car slowing at each box and a bat swinging, the car is {D}'s, and after {PRIOR} {DL} had every reason to know what a bat does to a mailbox.", "A registered owner is not always the driver, and the camera shows no face. The State must prove {D} was in that car, not merely that the car belongs to {D}."),
        timeline: [(0, "1 a.m.: mailboxes are smashed."), (1, "{V} finds the damage.")],
        identified: "A porch camera.",
        impact: "Four mailboxes on our road were smashed in a night, and mine was one of them. It's the second time in a year, and I had to buy a new post and box and wait for my mail at the post office. It feels like somebody just enjoys breaking other people's things.")

    static let expiredPermitAgain = SmallCases.make(
        key: "story.followup.expiredPermitAgain",
        category: .publicOrder,
        headlines: ["Defendant From Ballgame Case Stopped With Pistol in Console", "Second Concealed Weapon Charge"],
        law: "concealedWeapon",
        spec: "Carried a concealed pistol, on {DATE}.",
        ages: 21...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy stopped {D} for a tail light and found a loaded pistol in the console. {DL} says the permit had been renewed since.",
        state: [E(.physical, 3, "Pistol", "A loaded pistol in the console.", .search), E(.document, 3, "Permit Record", "The permit was still expired.")],
        defense: [E(.statement, 1, "Renewed", "{DL} says the permit was renewed.")],
        role: "Sheriff's deputy",
        exam: [.direct("What led to your stop of {DL}?", "\"I stopped {DL}'s car for a broken tail light on the county road, and asked for a license and registration.\""), .direct("What did you find?", "\"During the stop I saw a loaded pistol in the center console, in plain view when I looked in after {D.he} opened the console for papers.\""), .direct("What does the permit record show?", "\"The permit had expired months earlier, and the sheriff's records show no renewal on file at the time of the stop.\""), .direct("What does a concealed handgun permit require?", "\"It must be valid to carry a concealed handgun in a vehicle or on the person, and an expired permit doesn't count.\""), .direct("What did {DL} say?", "\"{D.He} said the permit had been renewed since and {D.he} believed it was current.\""), .direct("Did you check for a renewal?", "\"Yes. The sheriff's office had no renewal on file. I also checked the state database and found nothing active.\""), .cross("{DL} had a permit that had expired?", "\"Yes, and the expiration wasn't far back. A renewal can take time.\""), .cross("{DL} told you about a renewal right away?", "\"Yes, {D.he} told me at the stop that {D.he} had renewed.\""), .cross("The pistol was in the console, not on {DL}?", "\"That's right, in the center console, within reach but not on {D.his} person.\""), .cross("{DL} cooperated during the stop?", "\"Yes, {D.he} stayed calm and gave me the pistol when I asked.\""), .cross("You didn't see paper proof of renewal?", "\"No. {D.He} didn't have any paper with {D.him}, only the statement.\"")],
        theory: ("{D} carried without a permit.", "A renewed permit."),
        allocution: "\"I thought my permit had been renewed, and carrying the pistol in the console was habit. I've been in this courtroom before, and I should have checked the paperwork before I drove anywhere. I'll make sure it's in order or leave the gun at home.\"",
        truths: ("The renewal was never filed.", "A new card was mailed after the stop."),
        defendant: [.direct("Did you have a permit?", "\"I had a permit that had expired and I renewed it. I thought the renewal was complete when I carried.\""), .direct("Why did you carry the pistol?", "\"I drive at night for work and carry it for protection. I only carry when I think I'm allowed.\""), .direct("What did you understand about the renewal?", "\"I mailed the paperwork and the fee weeks earlier. I assumed the permit was good since I hadn't heard otherwise.\""), .direct("What happened at the stop?", "\"The deputy asked about the console, I told him about the permit and the pistol, and I handed it over.\""), .direct("Did you try to hide it?", "\"No. I was open about it. I told the deputy right away and cooperated with everything he asked.\""), .direct("What would you tell the court?", "\"I thought I was legal. I'd ask the court to see that I was waiting on the paperwork and meant no harm.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I knew how serious a permit matter is. I should have confirmed the renewal.\""), .cross("Your permit was expired?", "\"It was, and I should have checked before carrying. I take responsibility for that.\""), .cross("You had no proof of renewal with you?", "\"No, and I should have kept the paperwork in the car. That's a lesson I've learned.\""), .cross("You carried a loaded pistol in your console?", "\"Yes, and I know the rules. I should have left it home until the permit was confirmed.\""), .cross("You'll keep your permit current?", "\"Yes. I'll set a reminder and renew it far in advance, and I won't carry until I'm certain.\"")],
        openings: ("A deputy stopped {D} for a broken tail light, saw a loaded pistol in the console when {D} opened it for papers, and checked the permit record, which showed the permit still expired, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} had renewed the permit and believed it was current, and that the delay was paperwork, not intent. {D} told the deputy about the pistol and kept it in plain view."),
        closings: ("The permit record shows the permit was expired at the time of the stop, and after {PRIOR} {DL} knew to check the date before carrying a pistol.", "A renewed permit that had not yet posted is a paperwork lag, not a crime. The State must prove {D} knew the permit was expired and carried anyway."),
        timeline: [(0, "A deputy stops {DL}."), (0, "The pistol is found.")],
        identified: "A deputy's stop.",
        mood: .divided,
        genders: ["D": .male])

    static let raceDwlr = SmallCases.make(
        key: "story.followup.raceDwlr",
        category: .traffic,
        headlines: ["Driver in Race Wreck Caught Behind the Wheel With Suspended License", "Suspended Driver Stopped on County Road"],
        law: "dwlr",
        spec: "Operated a motor vehicle on a highway while {D.his} license was revoked, on {DATE}.",
        ages: 18...30,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D}'s license was suspended. A trooper stopped {DL} on the same county road. {DL} says {D.he} thought the suspension ended.",
        state: [E(.document, 3, "DMV Record", "An active suspension."), E(.statement, 2, "Trooper", "{D} said {D.he} thought it ended.")],
        defense: [E(.statement, 1, "Thought Ended", "{DL} says {D.he} thought the suspension ended.")],
        role: "State Highway Patrol trooper",
        exam: [.direct("What led you to stop {DL}?", "\"I was on patrol on a county road known for racing, and saw {DL}'s car pass another vehicle at high speed.\""), .direct("What did you do?", "\"I turned around, stopped {DL}'s car, and asked for a license and registration at the roadside.\""), .direct("What did you learn about the license?", "\"A DMV check showed {DL}'s license was under an active suspension from the earlier case at the time of the stop.\""), .direct("What does the DMV record show?", "\"It shows the suspension was still in effect and had not been lifted or restored by any court or DMV action.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} believed the suspension had ended and that {D.he} was driving legally.\""), .direct("Why does driving while revoked matter?", "\"It means the driver had notice and was barred from the road, and it puts everyone on the road at risk.\""), .cross("{DL} told you about the suspension right away?", "\"Yes, {D.he} said {D.he} thought it had ended, and didn't hide anything from me.\""), .cross("The suspension period was close to ending?", "\"It was near the end of the period, but it hadn't been formally lifted.\""), .cross("{DL} was cooperative during the stop?", "\"Yes, {D.he} was polite and answered questions without trouble.\""), .cross("{DL} wasn't impaired?", "\"No, I didn't smell alcohol or see signs of impairment.\""), .cross("A notice of reinstatement wasn't sent?", "\"I don't have one. The DMV record shows the suspension still active.\"")],
        theory: ("{D} drove suspended.", "A mistaken date."),
        allocution: "\"I shouldn't have driven. I thought the suspension had ended, and I needed to get to work, and I took the same county road I always take. I've been in this courtroom before, and I should have checked with the DMV. I'm sorry, and I'll find another way to work.\"",
        truths: ("The notice was signed for by {DL}.", "The DMV's online portal showed the suspension as ended."),
        defendant: [.direct("Why were you driving?", "\"I needed to get to work, and I believed my suspension was over, so I drove my car the way I normally would.\""), .direct("Why did you think it was over?", "\"I counted the time from the earlier case and thought it had passed, but I never confirmed it with the DMV.\""), .direct("Did you know you needed a restoration notice?", "\"I didn't understand that a suspension doesn't end until the DMV says so and I get my license back.\""), .direct("What happened at the stop?", "\"The trooper told me my license was suspended. I said I thought it had ended, and I didn't argue.\""), .direct("Were you racing?", "\"No. I passed a slow truck, which I shouldn't have done there. I wasn't racing anyone.\""), .direct("What would you tell the court?", "\"I made a mistake about the date. I'll confirm with the DMV before I drive again.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have been careful about the suspension. I wasn't.\""), .cross("You drove on a suspended license?", "\"I did, and I take responsibility. I should have checked.\""), .cross("You never called the DMV to confirm?", "\"No, and that was my mistake. I assumed time had passed.\""), .cross("You passed another car at speed?", "\"I did, and I shouldn't have. I'll drive more carefully.\""), .cross("You'll stay off the road until it's cleared?", "\"Yes. I'll arrange rides and I won't drive until the DMV gives me back my license.\"")],
        openings: ("A trooper on a county road known for racing watched {D}'s car pass another vehicle at high speed and stopped it. The DMV record shows {D}'s license was suspended, and {DL} came before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {D} thought the suspension had ended and had not received any notice that it was still in effect. {D} was honest with the trooper at the roadside."),
        closings: ("The DMV record shows an active suspension, and after {PRIOR} {D} knew a suspension must be cleared before driving. The trooper heard {D} say {D.he} thought it was over.", "A mistaken date is an honest mistake, not a choice to drive on a suspended license. The State must prove {D} knew the suspension was still in effect."),
        timeline: [(0, "A trooper stops {DL}."), (0, "The DMV record shows a suspension.")],
        identified: "A trooper's stop.",
        impact: "I live near that county road and saw the wreck there, and I've never forgotten it. When I heard the driver was back on the same road with a suspended license, it made my stomach turn. Someone is going to get hurt out there.")

    static let trailheadAgain = SmallCases.make(
        key: "story.followup.trailheadAgain",
        category: .property,
        headlines: ["Another Trailhead Car Smashed, Camera Catches Man", "Break-In Pattern at Trail Lots Traced to Defendant"],
        law: "breakingVehicle",
        spec: "Broke or entered a motor vehicle of {V} with intent to commit larceny therein, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a car at another trailhead was smashed and a purse taken. A trail camera caught {D} walking out. {DL} says {D.he} was hiking.",
        state: [E(.video, 3, "Trail Camera", "{D} walks out of the lot with a purse."), E(.physical, 3, "Purse", "{V}'s purse, found in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Hiking", "{DL} says {D.he} was hiking.")],
        role: "Car owner",
        exam: [.direct("What did you find when you returned to your car?", "\"The driver's window was smashed, glass was on the seat, and my purse was gone from under the seat.\""), .direct("Where were you?", "\"I'd gone for a short hike on a trail near the parking lot. I was away about two hours.\""), .direct("What was in the purse?", "\"My wallet, keys, phone, and some cash, and it was worth several hundred dollars with everything in it.\""), .direct("What did the trail camera show?", "\"It showed {DL} walking out of the lot carrying a purse that looked like mine.\""), .direct("How was the purse found?", "\"Deputies found it in {DL}'s car when they searched under a warrant, with my wallet and keys inside.\""), .direct("What did {DL} say?", "\"{D.He} said {D.he} was hiking and found the purse on the trail, and didn't take it from any car.\""), .cross("You didn't see anyone take the purse?", "\"No. I was on the trail and came back to a broken window.\""), .cross("The purse was found in {DL}'s car?", "\"Yes, deputies told me it was there with my wallet and keys.\""), .cross("{DL} could have found it on the trail?", "\"That's what {D.he} said, but it was in my car when I left it.\""), .cross("Nothing was missing from the purse?", "\"Some cash was gone, but the wallet and cards were still there.\""), .cross("The window was smashed?", "\"Yes, completely, and there was a rock on the floor of the car.\"")],
        theory: ("{D} smashed a window.", "A hiker."),
        allocution: "\"I'm sorry for what happened to that car. I was hiking on that trail that day, and I never broke into anything. I found a few things along the path, and I know how that looks. I've been in this courtroom before, and I'm asking the court to look closely.\"",
        truths: ("Glass was in {DL}'s hiking boots.", "The purse in {DL}'s car belonged to a hiker who left it at the ranger station table."),
        defendant: [.direct("What were you doing at the trailhead?", "\"I was hiking. I park there often, and I'd been on the trail most of the morning.\""), .direct("Where did you get the purse?", "\"I found it on the ground near the edge of the lot as I came back. It looked like someone had dropped it.\""), .direct("Why did you take it?", "\"I picked it up to turn it in at the ranger station, but I was in a hurry and put it in my car.\""), .direct("Did you break into any car?", "\"No. I would never do that. I didn't know whose purse it was or where it came from.\""), .direct("What did you do when the deputy found it?", "\"I told the deputy where I picked it up and that I meant to turn it in.\""), .direct("What would you tell the owner?", "\"I'm sorry for what happened to your car. I never broke in, and I'd have returned the purse if I'd gotten the chance.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I can see how this looks to anyone. I'm telling you the truth about where I found it.\""), .cross("You had the owner's wallet and keys in your car?", "\"Yes, and I should have handed them in right away. That was a mistake.\""), .cross("You walked out of the lot with a purse?", "\"I did, and the camera shows it. I thought it was lost, not stolen.\""), .cross("The window was smashed in that lot?", "\"So I'm told. I never touched that car or knew whose it was.\""), .cross("You'll return everything?", "\"Yes. I'll make sure the owner gets all of it, and I'll pay for the window if the court asks.\"")],
        openings: ("A car window at another trailhead was smashed and a purse taken from under the seat, and a trail camera shows {D} walking out of the lot with a purse, and {DL} had already appeared here in {PRIORDATE} over {PRIOR}.", "The defense will say {D} was out hiking and happened to walk through the lot, and that the purse in the picture is not shown to be the victim's. {D} broke no window."),
        closings: ("The camera shows {D} leaving the lot with a purse in hand, near a car with a smashed window. After {PRIOR}, {DL} knew what a trailhead lot is used for and what happens there.", "A hiker walking through a parking lot with a bag is not a thief. The State must prove {D} smashed the window and took the purse, and the camera does not show that."),
        timeline: [(0, "The window is smashed."), (0, "{DL} walks out with a purse.")],
        identified: "A trail camera.",
        impact: "It's the second time my car has been broken into at a trailhead. I came back from a hike to find the window shattered and my purse gone. I've loved those trails my whole life. Now I leave nothing in the car and still feel uneasy walking away. Again.",
        genders: ["D": .male])

    static let porchReturns = SmallCases.make(
        key: "story.followup.porchReturns",
        category: .family,
        headlines: ["Ex Seen at Woman's Door Again After Trespass Case", "Second Trespass Complaint Follows Earlier Case"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V} after being notified not to, on {DATE}.",
        ages: 20...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} appeared at {V}'s door again and waited 25 minutes. A doorbell camera showed it. {DL} says {D.he} came to apologize.",
        state: [E(.video, 3, "Doorbell Camera", "{D} waits at the door."), E(.document, 3, "Notice", "The written notice and a court order.")],
        defense: [E(.statement, 1, "Apology", "{DL} says {D.he} came to apologize.")],
        role: "Homeowner",
        exam: [.direct("What happened at your door that afternoon?", "\"I got a notification from my doorbell camera that someone was standing at my door, and I saw {DL} waiting there.\""), .direct("How long did {DL} stay?", "\"About twenty-five minutes. {D.He} knocked, rang the bell, and then just stood on the porch waiting.\""), .direct("Why were you afraid?", "\"{DL} had been told in writing and by a court order not to come to my home, and I hadn't invited {D.him}.\""), .direct("What does the notice say?", "\"It's a written notice and a court order barring {DL} from my property, which I served after the earlier case.\""), .direct("What did you do?", "\"I didn't open the door. I called the sheriff's office and watched {D.him} on the camera until deputies arrived.\""), .direct("What did {DL} say when the deputies came?", "\"{D.He} said {D.he} came to apologize for what happened and wanted to make peace.\""), .cross("{DL} didn't try to enter your house?", "\"No. {D.He} stayed on the porch and never tried the door.\""), .cross("{DL} didn't say anything threatening?", "\"I didn't hear anything. The camera has no sound of any threats.\""), .cross("{DL} left when the deputies asked?", "\"Yes, {D.he} left without any argument when they told {D.him} to go.\""), .cross("{DL} was polite on the video?", "\"Yes, {D.he} stood quietly and waved once at the camera.\""), .cross("You never answered the door?", "\"No. I didn't want any contact with {D.him} at all.\"")],
        theory: ("{D} returned.", "An apology."),
        allocution: "\"I went back to {V}'s door to apologize, and I waited because I wanted to say it in person. I know there's an order, and I've been in this courtroom before. I understand now that the apology should have been through the court. I won't go back.\"",
        truths: ("{DL} left flowers.", "{V}'s text two days earlier read 'ok, come by Sunday to talk.'"),
        defendant: [.direct("Why did you go to {V}'s house?", "\"I wanted to apologize for what happened in the earlier case. I thought saying it in person would settle things.\""), .direct("Did you know you weren't allowed?", "\"I knew about the order, but I thought an apology might be different. I didn't think it through.\""), .direct("Why did you stay so long?", "\"I was hoping {V} would come to the door. I thought if I waited, I'd get the chance to say I was sorry.\""), .direct("Did you mean to scare anyone?", "\"No. I never meant to frighten {V.him}. I stood quietly and I never tried the door.\""), .direct("What happened when the deputies came?", "\"I told them I came to apologize, and I left right away when they asked.\""), .direct("What would you tell {V}?", "\"I'm sorry for coming. I understand now that the order means no contact at all, even to say sorry.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know the order was meant to keep me away. I broke it.\""), .cross("You stood on the porch for twenty-five minutes?", "\"I did, and I understand how that looks to {V}. I regret it.\""), .cross("You had been told in writing not to come?", "\"Yes, and I shouldn't have. An apology wasn't a good enough reason.\""), .cross("{V} never invited you?", "\"No, and I should have known that meant no contact in any way.\""), .cross("You'll stay away from {V}'s home?", "\"Yes. I won't go near the house, and I'll send any apology through my lawyer.\"")],
        openings: ("After the written notice and court order from the earlier case over {PRIOR}, {D} came back to {V}'s door, knocked, rang the bell, and stood on the porch for twenty-five minutes while the doorbell camera recorded it, and {DL} had been before this court in {PRIORDATE}.", "The defense will say {D} came to apologize and never meant to scare or contact {V} against the order. {D} left when no one answered and made no threat."),
        closings: ("The notice and the court order told {D} to stay away, and {D} stood at {V}'s door for twenty-five minutes anyway. The camera records every minute.", "An apology offered at a door, without a threat, is not harassment. The State must prove {D} knew the order forbade it and intended to intrude on {V}."),
        timeline: [(0, "{DL} arrives."), (0, "{V} calls deputies.")],
        identified: "A doorbell camera.",
        mood: .wantsConviction,
        impact: "The court didn't stop it. {D.He} stood at my door for twenty-five minutes, and I watched {D.him} on the doorbell camera with my heart pounding. I told {D.him} through the glass to leave. I'd believed the order would keep my porch safe.",
        genders: ["D": .male, "V": .female])

    static let interfereAgain = SmallCases.make(
        key: "story.followup.interfereAgain",
        category: .publicOrder,
        headlines: ["911 Caller's Phone Taken Again", "Second Emergency-Line Interference Complaint"],
        law: "interferingEmergency",
        spec: "Willfully interfered with {V}'s communication with a 911 operator, on {DATE}.",
        ages: 19...55,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {V} began a second 911 call and the line went dead after a crash. {DL} says the phone slipped.",
        state: [E(.digital, 3, "911 Recording", "A shout and a crash."), E(.physical, 2, "Phone", "A phone on the floor.")],
        defense: [E(.statement, 1, "Slipped", "{DL} says the phone slipped.")],
        role: "911 dispatcher",
        exam: [.direct("What is your job?", "\"I'm a 911 dispatcher. I answer emergency calls, gather information, and send police, fire, and medical crews.\""), .direct("What did you receive that night?", "\"A 911 call came in, and the caller was starting to give an address when I heard a shout and a crash and then the line went dead.\""), .direct("What does the recording show?", "\"It shows a voice saying 'I need help,' a man's shout in the background, a crash, and then silence.\""), .direct("What did you do?", "\"I tried to call back and sent deputies to the address on the phone record. I kept trying the number.\""), .direct("What did deputies find?", "\"A phone on the floor, apparently thrown or knocked across the room, and {V} shaken but unhurt.\""), .direct("What did {DL} say?", "\"{D.He} said the phone slipped out of {V}'s hand during an argument and that {D.he} didn't touch it.\""), .cross("You can't tell who made the crash?", "\"No. I can only hear it. I can't tell what caused it.\""), .cross("The call disconnected, you didn't hear it cut?", "\"The line went silent after the crash. I don't know if it was dropped or disconnected.\""), .cross("You didn't hear {DL}'s voice?", "\"I heard a man's shout, but I can't identify it as {DL}'s.\""), .cross("The phone was found on the floor?", "\"Yes, deputies reported it was on the floor across the room.\""), .cross("Dispatch reached {V} afterward?", "\"We reached {V} after deputies arrived, and {V} confirmed what happened.\"")],
        theory: ("{D} interfered again.", "A slip."),
        allocution: "\"My phone slipped from my hand during the argument, and I didn't mean to cut off that 911 call. I'd never stop someone from getting help. I'm sorry for the fear it caused {V}.\"",
        truths: ("The same voice said 'give it.'", "The cracked phone was found under a couch where a dog had chewed it."),
        defendant: [.direct("What happened that night?", "\"We argued. {V} picked up the phone and I yelled, and the phone slipped and fell to the floor.\""), .direct("Did you take the phone from {V}?", "\"No. I never touched it. It slipped out of {V.his} hand when {V.he} was upset.\""), .direct("Why did you shout?", "\"I was angry and frustrated, and I raised my voice. I didn't mean to stop anyone from calling for help.\""), .direct("What was the crash?", "\"The phone hitting the floor and something falling off the shelf. It sounded worse than it was.\""), .direct("What did you do after?", "\"I stepped back and waited for the deputies. I didn't try to leave or hide.\""), .direct("What would you tell {V}?", "\"I'm sorry for frightening you. I never meant to keep you from getting help.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I understand why that makes people doubt me. I didn't touch the phone.\""), .cross("You were shouting while {V} called 911?", "\"Yes, and I regret it. I should have stayed quiet and let {V.him} make the call.\""), .cross("The call was cut off?", "\"Yes, and I didn't mean to cut it. It was an accident, but I understand how it sounded.\""), .cross("You didn't help {V} call back?", "\"No, I stood there. I should have helped, and I'm sorry I didn't.\""), .cross("You'll avoid arguments like that?", "\"Yes. I'll walk away when I'm angry and keep my distance from {V}.\"")],
        openings: ("A 911 caller, {V}, was starting to give an address when the dispatcher heard a shout and a crash and the line went dead. The recording shows a phone on the floor, and this was not {DL}'s first time here, after {PRIOR} in {PRIORDATE}.", "The defense will say {V}'s phone slipped from {V.his} hand and fell, and that {D} never grabbed or broke it. A dropped phone is an accident."),
        closings: ("The call dropped at the moment of a shout and a crash, and the phone was found on the floor. After {PRIOR}, {DL} knew what happens when someone reaches for a phone during an emergency call.", "A phone that slips from a hand is not interference. The State must prove {D} took or broke it to stop the call."),
        timeline: [(0, "{V} dials 911."), (0, "The line goes dead.")],
        identified: "A 911 recording.",
        mood: .wantsConviction,
        impact: "I started a 911 call and the line went dead after a crash. I held my phone in the dark and didn't know if anyone was coming. I'd done everything right and still felt alone. It's the second time this has happened to me. Again.",
        genders: ["D": .male, "V": .female])

    static let tillAgain = SmallCases.make(
        key: "story.followup.tillAgain",
        category: .whiteCollar,
        headlines: ["New Employer Reports Cash Missing After Clerk's Hiring", "Defendant From Embezzlement Case Under Suspicion Again"],
        law: "embezzlement",
        spec: "Embezzled $700 entrusted to {D} by {V}, a store owner, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} worked the register at a new store. {V} found $700 missing over two weeks. A camera shows {DL} taking bills. {DL} says the drawer was miscounted.",
        state: [E(.video, 3, "Register Camera", "{D} removes bills twice."), E(.document, 3, "Till Reports", "Short $700.")],
        defense: [E(.statement, 1, "Miscount", "{DL} says the drawer was miscounted.")],
        role: "Store owner",
        exam: [.direct("Who is {DL} to you?", "\"I hired {DL} to run the register at my store a few weeks before I noticed the shortages.\""), .direct("What did you notice?", "\"The register was short seven hundred dollars over two weeks, in amounts that didn't match sales or returns.\""), .direct("What do your till reports show?", "\"They show deposits that didn't match the cash count on shifts when {DL} worked alone.\""), .direct("What does the register camera show?", "\"It shows {DL} opening the drawer, taking bills twice, and putting them in a pocket.\""), .direct("Why did you hire {DL}?", "\"I knew about the earlier case, but I wanted to give {D.him} a chance. I trusted {D.him} with the drawer.\""), .direct("What did {DL} say?", "\"{D.He} said the drawer was miscounted and that {D.he} took change for lunch and did not steal.\""), .cross("You hired {DL} knowing the earlier case?", "\"Yes, I did, and I'd hoped it would work out.\""), .cross("Registers sometimes come up short by mistake?", "\"Occasionally, but not seven hundred dollars in two weeks, and not in a pattern.\""), .cross("The camera doesn't show how much was taken?", "\"The angle isn't clear on the amount, but it shows bills going into a pocket.\""), .cross("Other employees use the drawer?", "\"Yes, though the shortages only appeared on {DL}'s shifts.\""), .cross("{DL} was friendly with customers?", "\"Yes, {D.he} was good with customers, and I had no complaints about that.\"")],
        theory: ("{D} took from the till.", "A miscount."),
        allocution: "\"I'm sorry for the shortage at that store. I think the drawer was miscounted, and I was making change for customers all day. I've been in this courtroom before, and I know that makes me look guilty. I'd never take bills out of a register on purpose.\"",
        truths: ("The shortage began the week {DL} started.", "The drawer was shared with a second clerk who counted out at midnight."),
        defendant: [.direct("Did you take money from the register?", "\"I took a few dollars for lunch on shifts when it was slow, but I told the owner and meant to repay it.\""), .direct("Why did you take bills from the drawer?", "\"It was my lunch money and I took it out of the drawer instead of paying with my own. I thought it was fine.\""), .direct("Did you take seven hundred dollars?", "\"No. I never took anything like that. I think the drawer was miscounted or someone else took some.\""), .direct("How did you count the drawer?", "\"I counted at the start and end of my shift. I sometimes mixed bills and made mistakes.\""), .direct("What did the owner say?", "\"The owner showed me the reports and I was shocked. I told the truth and said I'd help figure it out.\""), .direct("What would you tell the owner?", "\"I'm sorry you trust me and I let you down. I'll repay what I took for lunch and help sort out the rest.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and that's why I should have been extra careful with cash.\""), .cross("The camera shows you taking bills?", "\"It does, and that was for lunch. I should have asked first.\""), .cross("You didn't tell the owner at the time?", "\"Not every time, and I should have. That was my mistake.\""), .cross("The shortages happened on your shifts?", "\"So I'm told, and I can't explain it except that I made counting mistakes.\""), .cross("You'll repay the owner?", "\"I'll repay what I took, and I'll cooperate with an audit if the owner wants one.\"")],
        openings: ("{D} worked the register at a new store, where {V} found $700 missing over two weeks in amounts that did not match sales or returns. The register camera shows {D} remove bills twice, and {DL} had faced this court in {PRIORDATE} over {PRIOR}.", "The defense will say the drawer was miscounted by several people during busy shifts, and the bills the camera shows {D} handling were change for customers. {D} never pocketed money."),
        closings: ("The register camera shows {D} lifting bills from the drawer, the till reports show a $700 shortage, and after {PRIOR} {DL} knew what is at stake when handling store cash.", "Several people use a drawer, counts are often wrong, and a camera of someone making change is not proof of theft. The State must prove {D} took the money."),
        timeline: [(-14, "{DL} starts."), (0, "The second night on video.")],
        identified: "A register camera.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "I hired this person in good faith after hearing about the earlier case, and seven hundred dollars went missing from my register in two weeks. It's a small store, and that loss came out of money for my own bills. I trusted someone, and I feel foolish about it.")

    static let cardAgain = SmallCases.make(
        key: "story.followup.cardAgain",
        category: .cyber,
        headlines: ["Second Card Opened in Roommate's Name", "Defendant From Identity Case Faces New Credit Fraud"],
        law: "cardFraud",
        spec: "Used a credit card belonging to {V} to obtain goods by fraud, on {DATE}.",
        ages: 19...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a new roommate, {V}, found a card statement for charges {V.he} never made. A store camera showed {D}. {DL} says {V} allowed it.",
        state: [E(.video, 3, "Store Camera", "{D} uses a card at a register."), E(.document, 3, "Statement", "$1,400 in charges.")],
        defense: [E(.statement, 1, "Allowed", "{DL} says {V} allowed it.")],
        role: "Roommate",
        exam: [.direct("How do you know {DL}?", "\"{DL} moved in as my roommate a few weeks before I found the charges on my card statement.\""), .direct("What did you find?", "\"A statement with about fourteen hundred dollars in charges at several stores that I never made.\""), .direct("What does the store camera show?", "\"It shows {DL} using a card at a register and walking out with several bags of merchandise.\""), .direct("How did {DL} get the card?", "\"It was in my wallet, which I kept in my bedroom. I didn't give {D.him} permission to use it.\""), .direct("What did you do?", "\"I called the bank, canceled the card, and reported the charges to the sheriff's office with the statement.\""), .direct("What did {DL} say?", "\"{D.He} said I allowed {D.him} to use the card and that I'd agreed to cover the purchases.\""), .cross("You and {DL} shared expenses?", "\"Yes, we split rent and groceries, but I never said {D.he} could use my credit card.\""), .cross("You didn't tell {DL} not to use it?", "\"I hadn't, because I never thought I'd have to. It was in my own room.\""), .cross("You didn't confront {DL} before reporting?", "\"I did mention the charges, but {D.he} said I'd allowed it, so I went to the bank.\""), .cross("You'd lent {DL} money before?", "\"A little, for groceries, but never my card.\""), .cross("The charges were all in the same week?", "\"Yes, within about nine days, at stores near our apartment.\"")],
        theory: ("{D} used a roommate's card.", "Permission."),
        allocution: "\"I used that card with {V}'s permission, and I believed it was fine. I've been in this courtroom before, and I know I should have gotten it in writing. I'll repay every charge, and I'll move out if that's what {V.he} wants.\"",
        truths: ("The card was in {V}'s drawer.", "{V} texted 'use it for groceries this week'."),
        defendant: [.direct("Why did you use the card?", "\"{V} told me I could use it for things for the apartment, and I thought that included what I bought.\""), .direct("What did you buy?", "\"Furniture, kitchen items, and some clothes. I thought they were for the apartment and for me.\""), .direct("Did {V} give you permission?", "\"I believe {V.he} said it was okay. We'd talked about sharing things, and I took that to include the card.\""), .direct("Why didn't you ask each time?", "\"We got along well and I didn't want to bother {V.him}. I should have asked before every purchase.\""), .direct("What happened when {V} found the charges?", "\"{V.He} was upset, and I told {V.him} I thought it was fine. I offered to pay back every dollar.\""), .direct("What would you tell {V}?", "\"I'm sorry for the misunderstanding. I'll repay what I spent and move out so you don't have to deal with me.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I should have been much more careful about using someone else's card.\""), .cross("You used {V}'s card without asking each time?", "\"Yes, and that was a mistake. Even if I thought it was okay, I should have asked.\""), .cross("Fourteen hundred dollars is a lot to spend on a roommate's card?", "\"It is, and I see that now. It added up faster than I realized.\""), .cross("You told the deputy {V} allowed it?", "\"I did, and I believed it. I understand now that {V.he} didn't.\""), .cross("You'll repay the fourteen hundred dollars?", "\"Yes. I'll set up a payment plan and make sure {V.he} gets it all back.\"")],
        openings: ("A few weeks after {D} moved in as a roommate, {V} found about $1,400 in charges on a card statement that {V.he} never made, and a store camera shows {D} using a card at the register, and {DL} had been before this court in {PRIORDATE} over {PRIOR}.", "The defense will say {V} gave permission to use the card for household purchases, and {D} used it as agreed. {D} never hid the purchases and kept the receipts."),
        closings: ("The statement lists charges {V} did not make, the camera shows {D} swiping the card, and after {PRIOR} {DL} knew to ask before using another person's card.", "A roommate who was given the card used it openly, in front of a camera, with receipts. The State must prove {V} did not allow it."),
        timeline: [(0, "{DL} uses the card."), (2, "{V} sees the statement.")],
        identified: "A store camera.",
        mood: .wantsConviction)

    static let grandmaSecondCheck = SmallCases.make(
        key: "story.followup.grandmaSecondCheck",
        category: .whiteCollar,
        headlines: ["Another Check From Same Account Cashed", "Defendant From Forgery Case Back at the Bank"],
        law: "uttering",
        spec: "Offered a forged check for $600 to a bank, knowing it to be forged, on {DATE}.",
        ages: 19...35,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a second check from {V}'s account was cashed by {D}. {V} had closed the account. {DL} says {V} wrote it before closing.",
        state: [E(.document, 3, "Check", "A $600 check on a closed account."), E(.statement, 3, "Teller", "{D} presented the check.")],
        defense: [E(.statement, 1, "Before Closing", "{DL} says {V} wrote it before closing.")],
        role: "Grandmother",
        exam: [.direct("What happened with your checking account?", "\"I'd closed it months earlier, and the bank told me a check for six hundred dollars on that account had been presented.\""), .direct("Who wrote the check?", "\"I didn't. It was a check from an old book I'd kept in a drawer, and the writing on it wasn't mine.\""), .direct("Why had you closed the account?", "\"I'd noticed missing checks after the earlier case, and I closed it to protect myself from further trouble.\""), .direct("What did the bank tell you?", "\"The teller said {DL} presented the check and tried to cash it, and the account was already closed.\""), .direct("Did you give {DL} permission?", "\"No. I never wrote or signed a check to {D.him}, and I'd told {D.him} not to take anything from me.\""), .direct("How has this affected you?", "\"It frightened me. I live on a small income and it hurts when family takes advantage of me.\""), .cross("You wrote checks to {DL} before?", "\"I have helped {D.him} before, but not with that check and not after closing the account.\""), .cross("The checkbook was in a drawer {DL} could reach?", "\"Yes, {D.he} visited often and could have found it.\""), .cross("You didn't see {DL} take it?", "\"No. I only learned about it when the bank called.\""), .cross("You wrote one check before closing the account?", "\"Possibly, but I don't remember writing one for six hundred dollars.\""), .cross("The bank called you first?", "\"Yes, the bank called me when the check was presented.\"")],
        theory: ("{D} cashed another forged check.", "An old check."),
        allocution: "\"{V.He} wrote that check before closing the account, and I cashed it believing it was good. I've been in this courtroom before, and I know I should have called {V.him} first. I'll repay the money and I'll stay in touch with {V.him}.\"",
        truths: ("The check was dated after the closing.", "A bank teller recalled {V} signing a blank checkbook in the lobby."),
        defendant: [.direct("Where did you get the check?", "\"My grandmother gave it to me before she closed the account. She wrote it for a repair on my car.\""), .direct("Why did you take it to the bank?", "\"I needed the money for the repair and thought the check was good. I didn't know the account was closed.\""), .direct("Did you sign or write anything on it?", "\"No. She wrote it out and signed it, and I only cashed it. I didn't alter anything.\""), .direct("What did the teller say?", "\"The teller said the account was closed. I was shocked and told her my grandmother gave it to me.\""), .direct("Why would your grandmother say she didn't?", "\"I think she forgot. She's older, and she's been confused about money since she closed the account.\""), .direct("What would you tell your grandmother?", "\"I'm sorry for the worry. I never meant to hurt you, and I'll pay back the six hundred dollars.\""), .cross("You had been in this courtroom before, hadn't you?", "\"Yes, and I know why it's hard to believe me. I still believe she wrote it.\""), .cross("Your grandmother says she didn't write it?", "\"That's what she says now. I think she doesn't remember, and I don't want to blame her.\""), .cross("You tried to cash a check on a closed account?", "\"I did, and I didn't know it was closed. If I had, I wouldn't have gone to the bank.\""), .cross("You can't prove she wrote it?", "\"Not with paper. I have only my word and what she told me then.\""), .cross("You'll repay the bank and your grandmother?", "\"Yes, whatever the court decides. I want to make this right.\"")],
        openings: ("After {V} closed the account months earlier, {D} presented a $600 check from an old book {V} kept in a drawer, and the teller cashed it. {V} says the writing on the check is not {V.his}, and {DL} had stood in this court in {PRIORDATE} over {PRIOR}.", "The defense will say {V} wrote the check before closing the account and {D} cashed it in good faith. {D} gave the teller {D.his} own ID and signed {D.his} own name."),
        closings: ("The account was closed, the check came from a drawer {D} could reach, and {V} did not write it. After {PRIOR}, {DL} knew exactly how this kind of check is cashed.", "An old check written before the account closed is not forgery. The State must prove {D} wrote or knew the check was false."),
        timeline: [(0, "{DL} cashes the check."), (1, "The bank flags the account.")],
        identified: "A teller.",
        mood: .divided,
        genders: ["V": .female])

